            if ones < k {
                if end == bytes.len() {
                    break;
                }
                ones += (b'1' == bytes[end]) as i32;
                end += 1;
                continue;
            }

            if ones == k {
                let candidate = &s[start..end];
                match substring {
                    None => substring = Some(candidate),
                    Some(cur)
                        if cur.len() > candidate.len()
                            || (cur.len() == candidate.len() && cur > candidate) =>
                    {
                        substring = Some(candidate)
                    }
                    _ => {}
                }
            }

            ones -= (b'1' == bytes[start]) as i32;
            start += 1;
        }

        match substring {
            None => "".to_owned(),
            Some(x) => x.to_owned(),
        }
    }
}

